<?php require __DIR__ . '/invitation-extra.php'; ?><?php if (!empty($invitation['id'])): try { $wishQuery=db()->prepare('SELECT name,message FROM wishes WHERE invitation_id=? AND status="approved" ORDER BY created_at DESC LIMIT 30'); $wishQuery->execute([$invitation['id']]); $approvedWishes=$wishQuery->fetchAll(); } catch(Throwable) { $approvedWishes=[]; } if($approvedWishes): ?><section><span class="eyebrow">WISHES</span><h2>Doa & ucapan</h2><?php foreach($approvedWishes as $wish): ?><article class="event"><strong><?= e($wish['name']) ?></strong><p><?= e($wish['message']) ?></p></article><?php endforeach; ?></section><?php endif; endif; ?>
